// server.js
import Stripe from 'stripe';
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.post('/create-checkout', async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: 'payment',
    line_items: [{
      price: 'price_1ABC123',  // your Stripe price ID
      quantity: 1,
    }],
    success_url: 'https://yourtool.com/success',
    cancel_url: 'https://yourtool.com/cancel',
  });
  res.json({ url: session.url });
});

// server.js - webhook handler
app.post('/webhook', express.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    // Mark user as paid in your database
    console.log('Payment succeeded:', session.customer_email);
  }
  res.json({ received: true });
});
